// Central table of the control / separator characters YAML cares about.
//
// Every one is built with String.fromCharCode rather than a "\u...." escape so
// that no raw U+0085 / U+2028 / U+2029 byte is ever embedded in a source file
// (a raw U+2028 inside a string literal is legal but hostile to tooling).

export const NUL = String.fromCharCode(0x00);
export const BELL = String.fromCharCode(0x07);
export const BACKSPACE = String.fromCharCode(0x08);
export const TAB = String.fromCharCode(0x09);
export const LF = String.fromCharCode(0x0a);
export const VTAB = String.fromCharCode(0x0b);
export const FF = String.fromCharCode(0x0c);
export const CR = String.fromCharCode(0x0d);
export const ESC = String.fromCharCode(0x1b);
export const SPACE = String.fromCharCode(0x20);
export const NEL = String.fromCharCode(0x85);
export const NBSP = String.fromCharCode(0xa0);
export const LS = String.fromCharCode(0x2028);
export const PS = String.fromCharCode(0x2029);
export const BOM = String.fromCharCode(0xfeff);

/** PyYAML's '\r\n\x85  ' — every character that ends a line. */
export const LINE_BREAKS = CR + LF + NEL + LS + PS;

/** PyYAML's '\0\r\n\x85  ' — line breaks plus end-of-stream. */
export const LINE_BREAKS_Z = NUL + LINE_BREAKS;

/** PyYAML's '\0 \t\r\n\x85  ' — whitespace, breaks and end-of-stream. */
export const BLANK_Z = NUL + SPACE + TAB + LINE_BREAKS;

/** PyYAML's ' \t' */
export const SPACES = SPACE + TAB;

/** PyYAML's ' \t\r\n\x85  ' */
export const BLANK = SPACES + LINE_BREAKS;

export const DIGITS = '0123456789';
export const HEX_DIGITS = '0123456789ABCDEFabcdef';
export const LETTERS_DIGITS =
  '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
/** Characters allowed in an alphanumeric-ish token body (anchors, tag handles). */
export const ALPHA = LETTERS_DIGITS + '-_';

/** Emitter table: character -> the letter that follows the backslash. */
export const EMIT_ESCAPES = new Map([
  [NUL, '0'],
  [BELL, 'a'],
  [BACKSPACE, 'b'],
  [TAB, 't'],
  [LF, 'n'],
  [VTAB, 'v'],
  [FF, 'f'],
  [CR, 'r'],
  [ESC, 'e'],
  ['"', '"'],
  ['\\', '\\'],
  [NEL, 'N'],
  [NBSP, '_'],
  [LS, 'L'],
  [PS, 'P'],
]);

/** Scanner table: the letter after a backslash -> the character it denotes. */
export const SCAN_ESCAPES = new Map([
  ['0', NUL],
  ['a', BELL],
  ['b', BACKSPACE],
  ['t', TAB],
  [TAB, TAB],
  ['n', LF],
  ['v', VTAB],
  ['f', FF],
  ['r', CR],
  ['e', ESC],
  [' ', SPACE],
  ['"', '"'],
  ['/', '/'],
  ['\\', '\\'],
  ['N', NEL],
  ['_', NBSP],
  ['L', LS],
  ['P', PS],
]);

/** Scanner table: the letter after a backslash -> how many hex digits follow. */
export const SCAN_ESCAPE_CODES = new Map([
  ['x', 2],
  ['u', 4],
  ['U', 8],
]);

