//   float           -> number          (1 and 1.0 must dump differently)
//   str             -> string
//   bytes           -> PyBytes
//   list            -> Array
//   tuple           -> PyTuple
//   set             -> PySet
//   dict            -> PyDict         (insertion ordered, Python key equality)
//   datetime.date     -> PyDate
//   datetime.datetime -> PyDateTime

import { PyTypeError } from './errors.mjs';

export class PyBytes {
  constructor(bytes) {
    this.bytes = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  }
}

export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

/** Python's datetime.date. */
export class PyDate {
  constructor(year, month, day) {
    this.year = year;
    this.month = month;
    this.day = day;
  }

  /** date.isoformat() */
  isoformat() {
    return `${pad(this.year, 4)}-${pad(this.month, 2)}-${pad(this.day, 2)}`;
  }
}

/**
 * Python's datetime.datetime. `tzOffsetMinutes` is null for a naive value, or
 * the UTC offset in minutes for an aware one.
 */
export class PyDateTime {
  constructor(year, month, day, hour, minute, second, microsecond, tzOffsetMinutes = null) {
    this.year = year;
    this.month = month;
    this.day = day;
    this.hour = hour;
    this.minute = minute;
    this.second = second;
    this.microsecond = microsecond;
    this.tzOffsetMinutes = tzOffsetMinutes;
  }

  /** datetime.isoformat(sep) — the form PyYAML's representer emits. */
  isoformat(sep = 'T') {
    let out = `${pad(this.year, 4)}-${pad(this.month, 2)}-${pad(this.day, 2)}${sep}` +
      `${pad(this.hour, 2)}:${pad(this.minute, 2)}:${pad(this.second, 2)}`;
    if (this.microsecond) out += '.' + pad(this.microsecond, 6);
    if (this.tzOffsetMinutes !== null) {
      const sign = this.tzOffsetMinutes < 0 ? '-' : '+';
      const abs = Math.abs(this.tzOffsetMinutes);
      out += `${sign}${pad(Math.floor(abs / 60), 2)}:${pad(abs % 60, 2)}`;
    }
    return out;
  }
}

function pad(n, width) {
  let s = String(n);
  while (s.length < width) s = '0' + s;
  return s;
}

/**
 * Canonical key for Python hash/equality semantics: `1`, `1.0` and `True`
 * all collide, as they do in a real dict. Throws for unhashable values.
 */
export function pyKey(value) {
  if (value === null) return 'N';
  if (value === true) return 'i1';
  if (value === false) return 'i0';
  if (typeof value === 'bigint') return 'i' + value.toString();
  if (typeof value === 'number') {
    if (Number.isFinite(value) && Number.isInteger(value)) return 'i' + BigInt(value).toString();
    if (Number.isNaN(value)) return 'fnan';
    return 'f' + String(value);
  }
  if (typeof value === 'string') return 's' + value;
  if (value instanceof PyBytes) {
    let s = 'b';
    for (const b of value.bytes) s += ',' + b;
    return s;
  }
  if (value instanceof PyTuple) {
    const parts = value.items.map((item) => pyKey(item).length + ':' + pyKey(item));
    return 't(' + parts.join(',') + ')';
