/** Insertion-ordered dict with Python key equality. */
export class PyDict {
  constructor() {
    this.map = new Map(); // canonical key -> [key, value]
  }

  get size() {
    return this.map.size;
  }

  set(key, value) {
    const k = pyKey(key);
    const existing = this.map.get(k);
    // Python keeps the *original* key object when a later assignment collides.
    if (existing !== undefined) existing[1] = value;
