  constructor(items = []) {
    this.map = new Map();
    for (const item of items) this.add(item);
  }

  get size() {
    return this.map.size;
  }

  add(item) {
    const k = pyKey(item);
    if (!this.map.has(k)) this.map.set(k, item);
  }

  has(item) {
    return this.map.has(pyKey(item));
  }

  values() {
    return [...this.map.values()];
