// ---------------------------------------------------------------------------
// repr(float)
// ---------------------------------------------------------------------------

/**
 * CPython's repr() for a finite float: shortest round-tripping digits, laid out
 * as fixed-point when -4 < decimal-point <= 16 and scientific otherwise, always
 * with a fractional part in fixed-point form.
 */
export function pyReprFloat(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';

  const negative = value < 0 || (value === 0 && 1 / value < 0);
  const abs = Math.abs(value);
  const sign = negative ? '-' : '';

  if (abs === 0) return sign + '0.0';

  // toExponential() with no argument yields the shortest digit string that
  // uniquely identifies the double — exactly what CPython's mode-0 dtoa gives.
  const exp = abs.toExponential();
  const eIndex = exp.indexOf('e');
  const mantissa = exp.slice(0, eIndex);
  const exponent = Number(exp.slice(eIndex + 1));
  const digits = mantissa.replace('.', '');
  // Position of the decimal point relative to the digit string.
  const decpt = exponent + 1;

  if (decpt > 16 || decpt < -3) {
    let out = digits[0];
    if (digits.length > 1) out += '.' + digits.slice(1);
    const e = decpt - 1;
    const esign = e < 0 ? '-' : '+';
    out += 'e' + esign + pad(Math.abs(e), 2);
    return sign + out;
  }

  if (decpt <= 0) return sign + '0.' + '0'.repeat(-decpt) + digits;
  if (decpt >= digits.length) {
    return sign + digits + '0'.repeat(decpt - digits.length) + '.0';
  }
  return sign + digits.slice(0, decpt) + '.' + digits.slice(decpt);
}

// ---------------------------------------------------------------------------
// Python comparison, used by the representer's `sorted(mapping.items())`
// ---------------------------------------------------------------------------

const NUMERIC = 1;
const STRING = 2;
const BYTES = 3;
const SEQUENCE = 4;
const DATE = 5;
const DATETIME = 6;
const UNORDERABLE = 0;

function orderClass(v) {
  if (typeof v === 'boolean' || typeof v === 'bigint' || typeof v === 'number') return NUMERIC;
  if (typeof v === 'string') return STRING;
  if (v instanceof PyBytes) return BYTES;
  if (Array.isArray(v) || v instanceof PyTuple) return SEQUENCE;
  if (v instanceof PyDate) return DATE;
  if (v instanceof PyDateTime) return DATETIME;
  return UNORDERABLE;
}

function toNumber(v) {
  if (typeof v === 'boolean') return v ? 1 : 0;
  if (typeof v === 'bigint') return v;
  return v;
}

/** Python's `a < b`, raising PyTypeError where Python raises TypeError. */
export function pyLessThan(a, b) {
  const ca = orderClass(a);
  const cb = orderClass(b);
  if (ca === UNORDERABLE || cb === UNORDERABLE || ca !== cb) {
    throw new PyTypeError(
      `'<' not supported between instances of '${pyTypeName(a)}' and '${pyTypeName(b)}'`);
  }
  switch (ca) {
    case NUMERIC: {
      const na = toNumber(a);
      const nb = toNumber(b);
      if (typeof na === 'bigint' && typeof nb === 'bigint') return na < nb;
      return Number(na) < Number(nb);
    }
    case STRING:
      return codePointLess(a, b);
    case BYTES:
      return bytesLess(a.bytes, b.bytes);
    case SEQUENCE: {
      // list and tuple are not mutually comparable in Python.
      const aIsTuple = a instanceof PyTuple;
      const bIsTuple = b instanceof PyTuple;
      if (aIsTuple !== bIsTuple) {
        throw new PyTypeError(
          `'<' not supported between instances of '${pyTypeName(a)}' and '${pyTypeName(b)}'`);
      }
      const xs = aIsTuple ? a.items : a;
      const ys = bIsTuple ? b.items : b;
      const n = Math.min(xs.length, ys.length);
      for (let i = 0; i < n; i++) {
        if (!pyEquals(xs[i], ys[i])) return pyLessThan(xs[i], ys[i]);
      }
      return xs.length < ys.length;
    }
    case DATE:
      return a.isoformat() < b.isoformat();
    case DATETIME:
      return compareDateTime(a, b) < 0;
    default:
      throw new PyTypeError('unorderable');
  }
}

/** Compare two strings by code point, the way Python compares str. */
function codePointLess(a, b) {
  const as = [...a];
  const bs = [...b];
  const n = Math.min(as.length, bs.length);
  for (let i = 0; i < n; i++) {
    const x = as[i].codePointAt(0);
    const y = bs[i].codePointAt(0);
    if (x !== y) return x < y;
  }
  return as.length < bs.length;
}

function bytesLess(a, b) {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    if (a[i] !== b[i]) return a[i] < b[i];
  }
  return a.length < b.length;
}

function compareDateTime(a, b) {
  // Aware and naive datetimes cannot be ordered against each other.
  if ((a.tzOffsetMinutes === null) !== (b.tzOffsetMinutes === null)) {
    throw new PyTypeError("can't compare offset-naive and offset-aware datetimes");
  }
  const ka = dateTimeSortKey(a);
  const kb = dateTimeSortKey(b);
  for (let i = 0; i < ka.length; i++) {
    if (ka[i] !== kb[i]) return ka[i] < kb[i] ? -1 : 1;
  }
  return 0;
}

function dateTimeSortKey(d) {
  const offset = d.tzOffsetMinutes === null ? 0 : d.tzOffsetMinutes;
  const days = daysFromCivil(d.year, d.month, d.day);
  const minutes = days * 1440 + d.hour * 60 + d.minute - offset;
  return [minutes, d.second, d.microsecond];
}

function daysFromCivil(y, m, d) {
  const yy = m <= 2 ? y - 1 : y;
  const era = Math.floor(yy / 400);
  const yoe = yy - era * 400;
  const mp = (m + 9) % 12;
  const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

/** Python's `a == b` for the value types we can produce. */
export function pyEquals(a, b) {
  const ca = orderClass(a);
  const cb = orderClass(b);
  if (a === null || b === null) return a === b;
  if (ca !== cb || ca === UNORDERABLE) {
    // Different families compare unequal rather than raising.
    if (ca === UNORDERABLE || cb === UNORDERABLE) {
      try {
        return pyKey(a) === pyKey(b);
      } catch {
        return a === b;
      }
    }
    return false;
  }
  try {
    return !pyLessThan(a, b) && !pyLessThan(b, a);
  } catch {
    return false;
  }
}

/**
 * CPython list.sort() for short lists: detect the initial run, reverse it if
 * descending, then binary-insertion-sort the remainder. Reproducing the real
 * comparison sequence matters because a TypeError from any single comparison is
 * what makes PyYAML fall back to insertion order.
 */
export function pySortInPlace(items, less) {
  const n = items.length;
  if (n < 2) return items;

  // count_run
  let runEnd = 2;
  let descending = false;
  if (less(items[1], items[0])) {
    descending = true;
    while (runEnd < n && less(items[runEnd], items[runEnd - 1])) runEnd++;
    // Reverse the strictly-descending prefix in place.
    for (let lo = 0, hi = runEnd - 1; lo < hi; lo++, hi--) {
      const t = items[lo];
      items[lo] = items[hi];
      items[hi] = t;
    }
  } else {
    while (runEnd < n && !less(items[runEnd], items[runEnd - 1])) runEnd++;
  }
  void descending;

  // binarysort: extend the sorted prefix one element at a time.
  for (let i = runEnd; i < n; i++) {
    const pivot = items[i];
    let lo = 0;
    let hi = i;
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (less(pivot, items[mid])) hi = mid;
      else lo = mid + 1;
    }
    for (let j = i; j > lo; j--) items[j] = items[j - 1];
    items[lo] = pivot;
  }
  return items;
}

// ---------------------------------------------------------------------------
// base64, matching Python's base64 module
// ---------------------------------------------------------------------------

const B64_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

/** base64.encodebytes(): wrapped at 76 characters, trailing newline. */
export function encodeBase64Wrapped(bytes) {
  let raw = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i];
    const b1 = i + 1 < bytes.length ? bytes[i + 1] : 0;
    const b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
    raw += B64_ALPHABET[b0 >> 2];
    raw += B64_ALPHABET[((b0 & 0x03) << 4) | (b1 >> 4)];
    raw += i + 1 < bytes.length ? B64_ALPHABET[((b1 & 0x0f) << 2) | (b2 >> 6)] : '=';
    raw += i + 2 < bytes.length ? B64_ALPHABET[b2 & 0x3f] : '=';
  }
  let out = '';
  for (let i = 0; i < raw.length; i += 76) out += raw.slice(i, i + 76) + '\n';
  if (raw.length === 0) out = '';
  return out;
}

/**
 * binascii.a2b_base64(): skip characters outside the alphabet, stop at padding,
 * and raise on a truncated final group.
 */
export function decodeBase64(text) {
  const values = [];
  for (const ch of text) {
    if (ch === '=') break;
    const idx = B64_ALPHABET.indexOf(ch);
    if (idx >= 0) values.push(idx);
  }
  if (values.length % 4 === 1) {
    const err = new Error('Invalid base64-encoded string: number of data characters (' +
      values.length + ') cannot be 1 more than a multiple of 4');
    err.qualifiedName = 'binascii.Error';
    throw err;
  }
  const out = [];
  for (let i = 0; i + 1 < values.length; i += 4) {
    const n = values.length - i;
    out.push(((values[i] << 2) | (values[i + 1] >> 4)) & 0xff);
    if (n >= 3) out.push(((values[i + 1] << 4) | (values[i + 2] >> 2)) & 0xff);
    if (n >= 4) out.push(((values[i + 2] << 6) | values[i + 3]) & 0xff);
  }
  return new Uint8Array(out);
}

