class Token {
  constructor(startMark, endMark) {
    this.startMark = startMark;
    this.endMark = endMark;
  }
}

function tokenClass(type, id, fields = []) {
  const cls = class extends Token {
    constructor(...args) {
      const startMark = args[fields.length];
      const endMark = args[fields.length + 1];
      super(startMark, endMark);
      fields.forEach((name, i) => { this[name] = args[i]; });
    }
  };
  Object.defineProperty(cls, 'name', { value: type });
  cls.prototype.tokenType = type;
  cls.prototype.id = id;
  return cls;
}

export const DirectiveToken = tokenClass('DirectiveToken', '<directive>', ['name', 'value']);
export const DocumentStartToken = tokenClass('DocumentStartToken', '<document start>');
export const DocumentEndToken = tokenClass('DocumentEndToken', '<document end>');
export const StreamStartToken = tokenClass('StreamStartToken', '<stream start>', ['encoding']);
export const StreamEndToken = tokenClass('StreamEndToken', '<stream end>');
export const BlockSequenceStartToken =
  tokenClass('BlockSequenceStartToken', '<block sequence start>');
export const BlockMappingStartToken =
  tokenClass('BlockMappingStartToken', '<block mapping start>');
export const BlockEndToken = tokenClass('BlockEndToken', '<block end>');
export const FlowSequenceStartToken = tokenClass('FlowSequenceStartToken', '[');
export const FlowMappingStartToken = tokenClass('FlowMappingStartToken', '{');
export const FlowSequenceEndToken = tokenClass('FlowSequenceEndToken', ']');
export const FlowMappingEndToken = tokenClass('FlowMappingEndToken', '}');
export const KeyToken = tokenClass('KeyToken', '?');
export const ValueToken = tokenClass('ValueToken', ':');
export const BlockEntryToken = tokenClass('BlockEntryToken', '-');
export const FlowEntryToken = tokenClass('FlowEntryToken', ',');
export const AliasToken = tokenClass('AliasToken', '<alias>', ['value']);
export const AnchorToken = tokenClass('AnchorToken', '<anchor>', ['value']);
export const TagToken = tokenClass('TagToken', '<tag>', ['value']);

export class ScalarToken extends Token {
  constructor(value, plain, startMark, endMark, style = null) {
    super(startMark, endMark);
