// Port of PyYAML's error.py — Mark and the YAMLError hierarchy.
// Error strings are reproduced character-for-character, since they surface in
// the traceback the CPython build prints on stderr.

import { LINE_BREAKS_Z as LINE_BREAK_CHARS } from './chars.mjs';

export class Mark {
  constructor(name, index, line, column, buffer, pointer) {
    this.name = name;
    this.index = index;
    this.line = line;
    this.column = column;
    this.buffer = buffer;
    this.pointer = pointer;
  }

  getSnippet(indent = 4, maxLength = 75) {
    if (this.buffer === null || this.buffer === undefined) return null;
    let head = '';
    let start = this.pointer;
    while (start > 0 && !LINE_BREAK_CHARS.includes(this.buffer[start - 1])) {
      start -= 1;
      if (this.pointer - start > maxLength / 2 - 1) {
        head = ' ... ';
        start += 5;
        break;
      }
    }
    let tail = '';
    let end = this.pointer;
    while (end < this.buffer.length && !LINE_BREAK_CHARS.includes(this.buffer[end])) {
      end += 1;
      if (end - this.pointer > maxLength / 2 - 1) {
        tail = ' ... ';
        end -= 5;
        break;
      }
    }
    const snippet = this.buffer.slice(start, end);
    return ' '.repeat(indent) + head + snippet + tail + '\n' +
      ' '.repeat(indent + this.pointer - start + head.length) + '^';
  }

  toString() {
    const snippet = this.getSnippet();
    let where = `  in "${this.name}", line ${this.line + 1}, column ${this.column + 1}`;
    if (snippet !== null) where += ':\n' + snippet;
    return where;
  }
}

export class YAMLError extends Error {
  constructor(message) {
    super(message);
    // `qualifiedName` mirrors how Python spells the class in a traceback.
    this.qualifiedName = 'yaml.error.YAMLError';
  }
}

export class MarkedYAMLError extends YAMLError {
  constructor(context = null, contextMark = null, problem = null, problemMark = null, note = null) {
    super('');
    this.context = context;
    this.contextMark = contextMark;
    this.problem = problem;
    this.problemMark = problemMark;
    this.note = note;
    this.message = this.buildMessage();
    this.qualifiedName = 'yaml.error.MarkedYAMLError';
  }

  buildMessage() {
    const lines = [];
    if (this.context !== null) lines.push(this.context);
    if (this.contextMark !== null &&
      (this.problem === null || this.problemMark === null ||
        this.contextMark.name !== this.problemMark.name ||
        this.contextMark.line !== this.problemMark.line ||
        this.contextMark.column !== this.problemMark.column)) {
      lines.push(String(this.contextMark));
    }
    if (this.problem !== null) lines.push(this.problem);
    if (this.problemMark !== null) lines.push(String(this.problemMark));
    if (this.note !== null) lines.push(this.note);
    return lines.join('\n');
  }

  toString() {
    return this.message;
  }
}

function markedSubclass(qualifiedName) {
  return class extends MarkedYAMLError {
    constructor(context, contextMark, problem, problemMark, note = null) {
      super(context, contextMark, problem, problemMark, note);
      this.qualifiedName = qualifiedName;
    }
  };
}

export class ReaderError extends YAMLError {
  constructor(name, position, character, encoding, reason) {
    super('');
    this.name = name;
    this.character = character;
    this.position = position;
    this.encoding = encoding;
    this.reason = reason;
    this.qualifiedName = 'yaml.reader.ReaderError';
    this.message = this.buildMessage();
  }

  buildMessage() {
    // The loader is always handed a str, so only PyYAML's unicode branch applies.
    const code = this.character.codePointAt(0).toString(16);
    return `unacceptable character #x${code}: ${this.reason}\n` +
      `  in "${this.name}", position ${this.position}`;
  }

  toString() { return this.message; }
}

export const ScannerError = markedSubclass('yaml.scanner.ScannerError');
export const ParserError = markedSubclass('yaml.parser.ParserError');
export const ComposerError = markedSubclass('yaml.composer.ComposerError');
export const ConstructorError = markedSubclass('yaml.constructor.ConstructorError');

export class SerializerError extends YAMLError {
  constructor(message) {
    super(message);
    this.qualifiedName = 'yaml.serializer.SerializerError';
  }
}

export class RepresenterError extends YAMLError {
  constructor(message) {
    super(message);
    this.qualifiedName = 'yaml.representer.RepresenterError';
  }
}

export class EmitterError extends YAMLError {
  constructor(message) {
    super(message);
    this.qualifiedName = 'yaml.emitter.EmitterError';
  }
}

// Stand-ins for the builtin Python exceptions PyYAML lets escape unchanged.
export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.qualifiedName = 'ValueError';
    this.message = message;
  }
}

export class PyTypeError extends Error {
  constructor(message) {
    super(message);
    this.qualifiedName = 'TypeError';
    this.message = message;
  }
}

