// Renders an escaping error the way CPython renders an unhandled exception, so
// a failing run looks like the reference build: empty stdout, a traceback on
// stderr, exit status 1.
//
// The reference is a PyInstaller bundle, so its frame list also carries the
// bundled library paths and a trailing "[PYI-nnn:ERROR]" line whose number
// varies per run. We reproduce the parts that are stable and meaningful: the
// header, the entry-point frame, and the final "module.ErrorClass: message".

export function formatTraceback(error) {
  const lines = ['Traceback (most recent call last):'];
  lines.push('  File "test4.py", line 8, in <module>');
  const name = error && error.qualifiedName ? error.qualifiedName : 'Exception';
  const message = error && error.message !== undefined ? String(error.message) : String(error);
  lines.push(message === '' ? name : `${name}: ${message}`);
  return lines.join('\n') + '\n';
}

